#!/usr/bin/env python3
"""Offline target planner and replay evidence reconciler.

Commands (see instruction.md for the full contract):

    ipv6_replay.py plan   MANIFEST.json
    ipv6_replay.py replay MANIFEST.json RESPONSES.jsonl

Everything is synthetic: no sockets, no packets, no external services.  Each
command writes exactly one JSON object to stdout and exits 0.  Whole-file
problems (bad arguments, invalid manifest, unreadable input, size/line limit
violations) exit 2 with an empty stdout and a stderr diagnostic.  Individual
malformed replay rows are quarantined into ``diagnostics`` instead.

The words internal/external describe observable response evidence only; they
never identify a device, prove a firewall policy, or assert reachability.
Silence stays inconclusive.
"""

import hashlib
import ipaddress
import json
import os
import re
import stat as stat_module
import sys

# ---------------------------------------------------------------------------
# Contract constants
# ---------------------------------------------------------------------------

MANIFEST_MAX_BYTES = 1024 * 1024          # 1 MiB
LOG_MAX_BYTES = 96 * 1024 * 1024          # 96 MiB
LOG_MAX_LINES = 300000                    # physical lines
LINE_MAX_BYTES = 4096                     # including the LF, when present
PROBE_ID_MAX_CHARS = 200
MAX_SEGMENTS = 2048                       # selected /64s over all windows
DOC_TOP32 = 0x20010DB8                    # 2001:db8::/32
CANARY_HIGH_BIT = 1 << 63
MAX_ADDRESS_CHARS = 45                    # longest legal IPv6 text form
CANARY_DOMAIN = 'ipv6-evidence-v1'

ID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
ADDRESS_CHARS = frozenset('0123456789abcdefABCDEF:.')
ROW_KEYS = frozenset(('probe_id', 'received_ms', 'target', 'source',
                      'type', 'code'))
TOP_KEYS = frozenset(('version', 'seed', 'low_count', 'attempts',
                      'spacing_ms', 'timeout_ms', 'windows'))
WINDOW_KEYS = frozenset(('id', 'start_ms', 'scopes'))
SCOPE_KEYS = frozenset(('id', 'prefix', 'subnets'))

CACHE_LIMIT = 262144
_text_cache = {}
_value_cache = {}


class Fatal(Exception):
    """A whole-file / argument error: exit 2, empty stdout, stderr note."""


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def _reject_constant(_value):
    raise Fatal('nonfinite JSON number')


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Fatal('duplicate JSON object key %r' % (key,))
        result[key] = value
    return result


def is_int(value):
    """True for JSON integers only: booleans and floats are excluded."""
    return isinstance(value, int) and not isinstance(value, bool)


def int_in_range(value, low, high, label):
    if not is_int(value):
        raise Fatal('%s must be an integer' % label)
    if value < low or value > high:
        raise Fatal('%s must lie in [%d, %d]' % (label, low, high))
    return value


def check_id(value, label):
    if not isinstance(value, str):
        raise Fatal('%s must be a string' % label)
    if ID_RE.match(value) is None:
        raise Fatal('%s %r is not a valid identifier' % (label, value))
    return value


def ipv6_value(text):
    """Strict IPv6 text -> 128-bit int inside 2001:db8::/32, else None.

    Rejects zone IDs, whitespace and every other non-address spelling; the
    remaining candidates are validated by ipaddress so that all legal text
    forms (uppercase, embedded dotted quads, compressed zeros) are accepted
    and compared by numeric value.
    """
    if not isinstance(text, str):
        return None
    length = len(text)
    if length == 0 or length > MAX_ADDRESS_CHARS:
        return None
    if not ADDRESS_CHARS.issuperset(text):
        return None
    try:
        value = int(ipaddress.IPv6Address(text))
    except (ValueError, TypeError):
        return None
    if (value >> 96) != DOC_TOP32:
        return None
    return value


def cached_ipv6_value(text):
    try:
        return _value_cache[text]
    except KeyError:
        pass
    value = ipv6_value(text)
    if len(_value_cache) < CACHE_LIMIT:
        _value_cache[text] = value
    return value


def address_text(value):
    """Canonical Python 3.11 spelling of a 128-bit address value."""
    try:
        return _text_cache[value]
    except KeyError:
        pass
    text = str(ipaddress.IPv6Address(value))
    if len(_text_cache) < CACHE_LIMIT:
        _text_cache[value] = text
    return text


def network_text(base):
    return address_text(base) + '/64'


def int_list(values):
    return '[' + ','.join([str(value) for value in values]) + ']'


def address_list(values):
    return ('[' + ','.join(['"%s"' % address_text(value) for value in values])
            + ']')


def mask_list(mask, attempts):
    return ('[' + ','.join([str(a) for a in range(attempts) if (mask >> a) & 1])
            + ']')


def read_bytes(path, max_bytes, label):
    if path == '-':
        raise Fatal('%s: stdin is not an accepted input' % label)
    try:
        handle = open(path, 'rb')
    except OSError as exc:
        raise Fatal('cannot open %s %r: %s' % (label, path, exc))
    with handle:
        try:
            info = os.fstat(handle.fileno())
        except OSError as exc:
            raise Fatal('cannot stat %s %r: %s' % (label, path, exc))
        if not stat_module.S_ISREG(info.st_mode):
            raise Fatal('%s %r is not a regular file' % (label, path))
        data = handle.read(max_bytes + 1)
    if len(data) > max_bytes:
        raise Fatal('%s %r exceeds the %d byte limit' % (label, path, max_bytes))
    return data


def parse_json_bytes(raw, label):
    if raw.startswith(b'\xef\xbb\xbf'):
        raise Fatal('%s starts with a UTF-8 BOM' % label)
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError as exc:
        raise Fatal('%s is not valid UTF-8: %s' % (label, exc))
    if text.startswith('\ufeff'):
        raise Fatal('%s starts with a BOM' % label)
    try:
        return json.loads(text, object_pairs_hook=_unique_object,
                          parse_constant=_reject_constant)
    except Fatal:
        raise
    except Exception as exc:
        raise Fatal('%s is not valid JSON: %s' % (label, exc))


def canary_iid(seed, window_id, scope_id, net_text):
    payload = ('%s\n%d\n%s\n%s\n%s\n' % (CANARY_DOMAIN, seed, window_id,
                                         scope_id, net_text)).encode('ascii')
    digest = hashlib.sha256(payload).digest()
    return int.from_bytes(digest[:8], 'big') | CANARY_HIGH_BIT


# ---------------------------------------------------------------------------
# Manifest validation
# ---------------------------------------------------------------------------

class Model(object):
    """A validated manifest plus its plan-ordered segments."""

    __slots__ = ('seed', 'low_count', 'attempts', 'spacing_ms', 'timeout_ms',
                 'windows', 'segments')


def parse_prefix(text, label):
    if not isinstance(text, str):
        raise Fatal('%s must be a string' % label)
    pieces = text.split('/')
    if len(pieces) != 2:
        raise Fatal('%s %r needs an explicit CIDR slash' % (label, text))
    length_text = pieces[1]
    if length_text == '56':
        length = 56
    elif length_text == '64':
        length = 64
    else:
        raise Fatal('%s %r must use /56 or /64' % (label, text))
    value = ipv6_value(pieces[0])
    if value is None:
        raise Fatal('%s %r is not an IPv6 address inside 2001:db8::/32'
                    % (label, text))
    mask = ((1 << length) - 1) << (128 - length)
    if value & ~mask:
        raise Fatal('%s %r has host bits set' % (label, text))
    return value, length


def validate_manifest(document):
    if not isinstance(document, dict):
        raise Fatal('manifest must be a JSON object')
    if document.keys() != TOP_KEYS:
        raise Fatal('manifest must have exactly the keys %s' % sorted(TOP_KEYS))
    if not is_int(document['version']) or document['version'] != 1:
        raise Fatal('version must be integer 1')
    seed = int_in_range(document['seed'], 0, (1 << 64) - 1, 'seed')
    low_count = int_in_range(document['low_count'], 1, 32, 'low_count')
    attempts = int_in_range(document['attempts'], 1, 3, 'attempts')
    spacing_ms = int_in_range(document['spacing_ms'], 1, 1000, 'spacing_ms')
    timeout_ms = int_in_range(document['timeout_ms'], 1, 1000000, 'timeout_ms')
    raw_windows = document['windows']
    if not isinstance(raw_windows, list):
        raise Fatal('windows must be an array')
    if len(raw_windows) > 8:
        raise Fatal('windows must hold at most 8 entries')

    model = Model()
    model.seed = seed
    model.low_count = low_count
    model.attempts = attempts
    model.spacing_ms = spacing_ms
    model.timeout_ms = timeout_ms
    model.windows = []
    model.segments = []

    window_ids = set()
    total_selected = 0
    for raw_window in raw_windows:
        if not isinstance(raw_window, dict):
            raise Fatal('each window must be an object')
        if raw_window.keys() != WINDOW_KEYS:
            raise Fatal('window must have exactly the keys %s'
                        % sorted(WINDOW_KEYS))
        window_id = check_id(raw_window['id'], 'window id')
        if window_id in window_ids:
            raise Fatal('duplicate window id %r' % window_id)
        window_ids.add(window_id)
        start_ms = int_in_range(raw_window['start_ms'], 0, 10 ** 12, 'start_ms')
        raw_scopes = raw_window['scopes']
        if not isinstance(raw_scopes, list):
            raise Fatal('scopes must be an array')
        if len(raw_scopes) > 32:
            raise Fatal('a window holds at most 32 scopes')

        scopes = []
        scope_ids = set()
        window_bases = set()
        for raw_scope in raw_scopes:
            if not isinstance(raw_scope, dict):
                raise Fatal('each scope must be an object')
            if raw_scope.keys() != SCOPE_KEYS:
                raise Fatal('scope must have exactly the keys %s'
                            % sorted(SCOPE_KEYS))
            scope_id = check_id(raw_scope['id'], 'scope id')
            if scope_id in scope_ids:
                raise Fatal('duplicate scope id %r in window %r'
                            % (scope_id, window_id))
            scope_ids.add(scope_id)
            base, length = parse_prefix(raw_scope['prefix'], 'prefix')
            raw_subnets = raw_scope['subnets']
            if not isinstance(raw_subnets, list):
                raise Fatal('subnets must be an array')
            for item in raw_subnets:
                if not is_int(item):
                    raise Fatal('subnets must contain integers')
            if len(set(raw_subnets)) != len(raw_subnets):
                raise Fatal('subnets must be distinct')
            if length == 56:
                if not 1 <= len(raw_subnets) <= 256:
                    raise Fatal('a /56 selects 1 to 256 subnets')
                for item in raw_subnets:
                    if item < 0 or item > 255:
                        raise Fatal('/56 subnet values must lie in [0, 255]')
                selected = sorted(raw_subnets)
            else:
                if raw_subnets != [0]:
                    raise Fatal('a /64 prefix must select exactly [0]')
                selected = [0]
            entries = []
            for subnet in selected:
                net_base = (base | (subnet << 64)) if length == 56 else base
                if net_base in window_bases:
                    raise Fatal('selected /64s overlap inside window %r'
                                % window_id)
                window_bases.add(net_base)
                entries.append((subnet, net_base))
            total_selected += len(entries)
            if total_selected > MAX_SEGMENTS:
                raise Fatal('at most %d /64s may be selected' % MAX_SEGMENTS)
            scopes.append({'id': scope_id, 'entries': entries})
        model.windows.append({'id': window_id, 'start_ms': start_ms,
                              'scopes': scopes})

    # Plan order: windows by id (ASCII), scopes by id, subnets numerically.
    model.windows.sort(key=lambda window: window['id'])
    segments = model.segments
    for window in model.windows:
        window['scopes'].sort(key=lambda scope: scope['id'])
        for scope in window['scopes']:
            ordered = []
            for subnet, net_base in scope['entries']:
                text = network_text(net_base)
                segments.append({
                    'window': window['id'],
                    'scope': scope['id'],
                    'subnet': subnet,
                    'base': net_base,
                    'network': text,
                    'c0': canary_iid(seed, window['id'], scope['id'], text),
                })
                ordered.append(len(segments) - 1)
            scope['segments'] = ordered
            del scope['entries']
    return model


def load_model(path):
    raw = read_bytes(path, MANIFEST_MAX_BYTES, 'manifest')
    return validate_manifest(parse_json_bytes(raw, 'manifest'))


# ---------------------------------------------------------------------------
# Plan enumeration
# ---------------------------------------------------------------------------

def iter_plan(model):
    """Yield every scheduled probe in plan order.

    Tuple: (window_id, scope_id, subnet, segment_index, role, slot, attempt,
            target_value, target_text, sent_ms, deadline_ms)
    """
    low_count = model.low_count
    attempts = model.attempts
    spacing_ms = model.spacing_ms
    timeout_ms = model.timeout_ms
    segments = model.segments
    low_targets = [('low', iid, iid) for iid in range(1, low_count + 1)]
    for window in model.windows:
        window_id = window['id']
        start_ms = window['start_ms']
        ordinal = 0
        for scope in window['scopes']:
            scope_id = scope['id']
            for segment_index in scope['segments']:
                segment = segments[segment_index]
                base = segment['base']
                subnet = segment['subnet']
                c0 = segment['c0']
                targets = low_targets
                targets = targets + [('canary', 0, c0), ('canary', 1, c0 ^ 1)]
                for role, slot, iid in targets:
                    target = base | iid
                    text = address_text(target)
                    for attempt in range(attempts):
                        sent = start_ms + ordinal * spacing_ms
                        yield (window_id, scope_id, subnet, segment_index,
                               role, slot, attempt, target, text, sent,
                               sent + timeout_ms)
                        ordinal += 1
